package com.zxl.zxlaiagent.knowledge.gateway;
import com.sun.net.httpserver.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.zxl.zxlaiagent.knowledge.*;
import com.zxl.zxlaiagent.knowledge.scoped.*;
import com.zxl.zxlaiagent.knowledge.retrieval.Reranker;
import com.zxl.zxlaiagent.security.*;
import org.junit.jupiter.api.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
class ScopedKnowledgeClientPgTest {
 static final String TOKEN="abcdefghijklmnopqrstuvwxyz_0123456789-ABCDEFGHIJKLMNO";
 SecurityDatabase security;KnowledgeDatabase db;AuthenticationService auth;AuthorizationService authorization;ServiceCallAuthorizer tickets;ScopedKnowledgeFactory factory;ActorRef alice,bob;String a,b;HttpServer server;
 @BeforeEach void setup()throws Exception{security=SecurityDatabase.fromEnvironment();db=new KnowledgeDatabase(System.getenv("LESSON12_DB_URL"),System.getenv("LESSON12_DB_USER"),System.getenv("LESSON12_DB_PASSWORD"));auth=new AuthenticationService(security);authorization=new AuthorizationService(security);tickets=new ServiceCallAuthorizer(security,authorization);a="gateway-"+UUID.randomUUID();b="gateway-"+UUID.randomUUID();auth.provision(a,a,"synthetic-password",a,"knowledge-maintainer");auth.provision(b,b,"synthetic-password",b,"knowledge-maintainer");alice=auth.login(a,"synthetic-password",a).actor().ref();bob=auth.login(b,"synthetic-password",b).actor().ref();factory=new ScopedKnowledgeFactory(db,authorization,new DemoKnowledgeEmbedding(),Reranker.rules(),null,Clock.systemUTC());server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);}
 @AfterEach void cleanup(){if(server!=null)server.stop(0);db.tx(c->{for(String tenant:List.of(a,b))for(String table:List.of("knowledge_chunk","knowledge_revision","knowledge_document")){try(var s=KnowledgeDatabase.statement(c,"DELETE FROM "+table+" WHERE tenant_id=?",tenant)){s.executeUpdate();}}return null;});security.tx(c->{for(String id:List.of(a,b)){try(var s=SecurityDatabase.statement(c,"DELETE FROM authorization_audit WHERE subject_id=?",id)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"DELETE FROM subject WHERE subject_id=?",id)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"DELETE FROM tenant WHERE tenant_id=?",id)){s.executeUpdate();}}return null;});}
 ScopedKnowledgeClient client(){return new ScopedKnowledgeClient(URI.create("http://127.0.0.1:"+server.getAddress().getPort()),TOKEN,tickets,authorization);}
 ActorRef consume(HttpExchange exchange,byte[] body){assertEquals("Bearer "+TOKEN,exchange.getRequestHeaders().getFirst("Authorization"));assertNull(exchange.getRequestHeaders().getFirst("Cookie"));return tickets.consume(exchange.getRequestHeaders().getFirst("X-Service-Ticket"),WorkerRequestContract.AUDIENCE,WorkerRequestContract.action(exchange.getRequestMethod(),exchange.getRequestURI().getPath()),WorkerRequestContract.hash(exchange.getRequestMethod(),exchange.getRequestURI().getPath(),exchange.getRequestURI().getRawQuery(),body));}
 void reply(HttpExchange exchange,int code,byte[] bytes)throws java.io.IOException{try{exchange.sendResponseHeaders(code,bytes.length);exchange.getResponseBody().write(bytes);}finally{exchange.close();}}
 @Test void originalBytesAndActorTicketsReachRealPgScopes()throws Exception{
  var bodies=new CopyOnWriteArrayList<String>();var queries=new CopyOnWriteArrayList<String>();var json=new ObjectMapper();server.createContext(WorkerRequestContract.BASE,exchange->{try{byte[] body=exchange.getRequestBody().readAllBytes();ActorRef actor=consume(exchange,body);queries.add(String.valueOf(exchange.getRequestURI().getRawQuery()));Object response;if(exchange.getRequestMethod().equals("POST")){String text=new String(body,StandardCharsets.UTF_8);bodies.add(text);var node=json.readTree(body);response=factory.knowledge(actor).importDocument(node.path("documentId").asText(),node.path("sourceName").asText(),node.path("content").asText());}else response=factory.knowledge(actor).detail("same");reply(exchange,200,json.writeValueAsBytes(response));}catch(SecurityFailure denied){reply(exchange,denied.status(),"{}".getBytes());}});server.start();
  String first="{ \"documentId\" : \"same\", \"sourceName\":\"a.md\", \"content\":\"alpha secret\" }",second="{\"documentId\":\"same\",\"sourceName\":\"b.md\",\"content\":\"beta secret\"}";var client=client();assertEquals(200,client.exchange(alice,"POST",WorkerRequestContract.BASE+"/documents",null,first.getBytes(StandardCharsets.UTF_8),Duration.ofSeconds(10)).status());assertEquals(200,client.exchange(bob,"POST",WorkerRequestContract.BASE+"/documents",null,second.getBytes(StandardCharsets.UTF_8),Duration.ofSeconds(10)).status());assertEquals(List.of(first,second),bodies);
  var response=client.exchange(bob,"GET",WorkerRequestContract.BASE+"/documents/same","q=a+b&limit=5",new byte[0],Duration.ofSeconds(10));String text=new String(response.body(),StandardCharsets.UTF_8);assertTrue(text.contains("beta secret"));assertFalse(text.contains("alpha secret"));assertEquals("limit=5&q=a%20b",queries.get(2));
 }
 @Test void consumedTicketRejectsTamperedBytesWithoutRetry()throws Exception{AtomicInteger calls=new AtomicInteger();server.createContext(WorkerRequestContract.BASE,exchange->{calls.incrementAndGet();byte[] body=exchange.getRequestBody().readAllBytes();try{consume(exchange,(new String(body,StandardCharsets.UTF_8)+" ").getBytes(StandardCharsets.UTF_8));reply(exchange,200,"{}".getBytes());}catch(SecurityFailure denied){reply(exchange,denied.status(),"{}".getBytes());}});server.start();var response=client().exchange(alice,"POST",WorkerRequestContract.BASE+"/documents",null,"{}".getBytes(),Duration.ofSeconds(5));assertEquals(401,response.status());assertEquals(1,calls.get());}
 @Test void identityFieldsUnknownQueriesAndHugeRequestsNeverDispatch(){AtomicInteger calls=new AtomicInteger();server.createContext(WorkerRequestContract.BASE,exchange->{calls.incrementAndGet();reply(exchange,200,"{}".getBytes());});server.start();var client=client();String path=WorkerRequestContract.BASE+"/answers";for(String body:List.of("{\"profile\":\"alice\"}","{\"tenantId\":\"other\"}","{\"actor\":{\"subjectId\":\"other\"}}","{} {}","{\"question\":1,\"question\":2}")){assertEquals(400,assertThrows(SecurityFailure.class,()->client.exchange(alice,"POST",path,null,body.getBytes(),Duration.ofSeconds(5))).status());}assertThrows(SecurityFailure.class,()->client.exchange(alice,"GET",WorkerRequestContract.BASE+"/documents","profile=alice",new byte[0],Duration.ofSeconds(5)));assertThrows(SecurityFailure.class,()->client.exchange(alice,"POST",path,null,new byte[ScopedKnowledgeClient.MAX_REQUEST_BYTES+1],Duration.ofSeconds(5)));assertEquals(0,calls.get());}
 @Test void revocationWhileWorkerWaitsReleasesGateAndDiscardsResponse()throws Exception{var started=new CountDownLatch(1);var release=new CountDownLatch(1);server.createContext(WorkerRequestContract.BASE,exchange->{consume(exchange,exchange.getRequestBody().readAllBytes());started.countDown();try{release.await(10,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}reply(exchange,200,"{\"secret\":\"unpublished\"}".getBytes());});server.start();var pool=Executors.newSingleThreadExecutor();try{var pending=pool.submit(()->client().exchange(alice,"GET",WorkerRequestContract.BASE+"/documents",null,new byte[0],Duration.ofSeconds(10)));assertTrue(started.await(5,TimeUnit.SECONDS));auth.revoke(alice);release.countDown();var failure=assertThrows(ExecutionException.class,()->pending.get(5,TimeUnit.SECONDS));assertInstanceOf(SecurityFailure.class,failure.getCause());assertEquals(401,((SecurityFailure)failure.getCause()).status());}finally{release.countDown();pool.shutdownNow();}}
 @Test void oversizedResponseAndSlowBodyAreBoundedWithoutRetry()throws Exception{var calls=new AtomicInteger();var slow=new AtomicBoolean(false);var release=new CountDownLatch(1);server.createContext(WorkerRequestContract.BASE,exchange->{calls.incrementAndGet();consume(exchange,exchange.getRequestBody().readAllBytes());if(!slow.get()){try{reply(exchange,200,new byte[ScopedKnowledgeClient.MAX_RESPONSE_BYTES+1]);}catch(java.io.IOException cancelled){exchange.close();}}else{exchange.sendResponseHeaders(200,4);try{release.await(5,TimeUnit.SECONDS);exchange.getResponseBody().write("body".getBytes());}catch(Exception cancelled){}finally{exchange.close();}}});server.start();var client=client();assertEquals(502,assertThrows(SecurityFailure.class,()->client.exchange(alice,"GET",WorkerRequestContract.BASE+"/documents",null,new byte[0],Duration.ofSeconds(5))).status());slow.set(true);long before=System.nanoTime();try{assertEquals(504,assertThrows(SecurityFailure.class,()->client.exchange(alice,"GET",WorkerRequestContract.BASE+"/documents",null,new byte[0],Duration.ofMillis(800))).status());assertTrue((System.nanoTime()-before)/1_000_000<1800);}finally{release.countDown();}assertEquals(2,calls.get());}

 @Test void javaRunPermissionsAreCombinedBeforeDispatch(){AtomicInteger calls=new AtomicInteger();server.createContext(WorkerRequestContract.BASE,exchange->{calls.incrementAndGet();reply(exchange,200,"{}".getBytes());});server.start();String other=UUID.randomUUID().toString();authorization.registerResource(bob,new ResourceRef("conversation",other));var permissions=List.of(new AuthorizationService.Permission("conversation.readOwn",new ResourceRef("conversation",other)));var failure=assertThrows(SecurityFailure.class,()->client().exchange(alice,"GET",WorkerRequestContract.BASE+"/documents",null,new byte[0],Duration.ofSeconds(5),()->false,permissions,null));assertEquals(404,failure.status());assertEquals(0,calls.get());}
 @Test void cancellationFlagStopsPendingBodyWithoutThreadInterrupt()throws Exception{var started=new CountDownLatch(1);var release=new CountDownLatch(1);var cancelled=new AtomicBoolean(false);String own=UUID.randomUUID().toString();authorization.registerResource(alice,new ResourceRef("conversation",own));var permissions=List.of(new AuthorizationService.Permission("conversation.readOwn",new ResourceRef("conversation",own)));server.createContext(WorkerRequestContract.BASE,exchange->{consume(exchange,exchange.getRequestBody().readAllBytes());exchange.sendResponseHeaders(200,4);started.countDown();try{release.await(10,TimeUnit.SECONDS);exchange.getResponseBody().write("body".getBytes());}catch(Exception ignored){}finally{exchange.close();}});server.start();var pool=Executors.newSingleThreadExecutor();try{var pending=pool.submit(()->client().exchange(alice,"GET",WorkerRequestContract.BASE+"/documents",null,new byte[0],Duration.ofSeconds(10),cancelled::get,permissions,own));assertTrue(started.await(5,TimeUnit.SECONDS));long before=System.nanoTime();cancelled.set(true);var failure=assertThrows(ExecutionException.class,()->pending.get(2,TimeUnit.SECONDS));assertEquals("KNOWLEDGE_CANCELLED",((SecurityFailure)failure.getCause()).code());assertTrue((System.nanoTime()-before)/1_000_000<1000);}finally{release.countDown();pool.shutdownNow();}}
}
